import{_ as a,o as t,c as r,a6 as o}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"動作要件","description":"","frontmatter":{"title":"動作要件","docId":"user.start.requirements","translationKey":"user.start.requirements","locale":"ja","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"c68c149552a943cf0f03393c5dac91bd62abf9c50f791d7b0757599754f4804e","translationRevision":"f64cebdff874245ee781e84f4f79bd6d6993bd5ba1ed4da639ebd83b9a1ade01","order":10},"headers":[],"relativePath":"ja/user/requirements.md","filePath":"ja/user/requirements.md","lastUpdated":1794611623000}'),i={name:"ja/user/requirements.md"};function l(n,e,d,s,c,u){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="requirements" tabindex="-1">動作要件 <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;動作要件 {#requirements}&quot;">​</a></h1><h2 id="goal" tabindex="-1">目的 <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;目的 {#goal}&quot;">​</a></h2><p>インストール前に対応デスクトップパッケージを選び、目的の用途に必要なサービスを確認します。</p><h2 id="what-you-need" tabindex="-1">必要なもの <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;必要なもの {#what-you-need}&quot;">​</a></h2><ul><li>公開デスクトップパッケージ用の Windows x86_64 または Linux x86_64 PC。現在のリリース処理はこの2対象をビルドし、macOS デスクトップ版や Android APK は公開しません。</li><li>正常なグラフィカルセッション。Windows は Microsoft WebView2 Runtime、Linux は互換性のある GTK/WebKitGTK 環境が必要です。DEB は実行時パッケージを依存関係として宣言し、AppImage は確認済みメディア補助機能を同梱します。</li><li>実際の LIVE 接続には TikTok へのネットワークアクセス。配信終了、ゲストセッションの期限切れ、配信元のレート制限は自動化を変更しても直りません。</li><li>SQLite データ、プラグイン、ログを保存する、インストール先とは別の領域。アプリはユーザーごとのデータディレクトリを使い、実行ファイルを移動してもデータは移動しません。</li></ul><p>Cloud アカウントはアカウント方式のカタログや共同操作に必要で、すべてのローカル編集に必要なわけではありません。OBS は配信にウィジェットを表示する場合だけ必要です。音声・TTS 連携には、別途インストールするプラグインと専用のプロバイダー・サービスが必要な場合があります。</p><h2 id="check-the-environment" tabindex="-1">環境を確認する <a class="header-anchor" href="#check-the-environment" aria-label="Permalink to &quot;環境を確認する {#check-the-environment}&quot;">​</a></h2><ol><li>OS と x86_64 アーキテクチャに合うパッケージを選びます。</li><li>Windows のインストーラーが不足を報告したら WebView2 をインストールします。Linux の不足ライブラリはディストリビューションのパッケージマネージャーで解決します。</li><li>TikTok 接続やプラグイン追加の前に、アプリのウィンドウが開くことを確認します。</li><li><a href="./installation.html">インストール</a>、<a href="./first-live.html">最初の LIVE</a> の順に進みます。</li></ol><h2 id="expected-result" tabindex="-1">期待される結果 <a class="header-anchor" href="#expected-result" aria-label="Permalink to &quot;期待される結果 {#expected-result}&quot;">​</a></h2><p>オフラインでもアプリが開き、メインナビゲーションを使えます。任意の連携は、プラグインやホスト機能が揃うまで使えない場合があります。</p><h2 id="recovery" tabindex="-1">問題が起きたとき <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;問題が起きたとき {#recovery}&quot;">​</a></h2><p>空白ウィンドウや起動直後の終了では、起動診断と正確なパッケージバージョンを記録します。AppImage と DEB は異なるインストール形式で、どちらも Android 実行ファイルではありません。その環境については <a href="./termux.html">Termux とヘッドレスの対応範囲</a> を参照します。ソースビルドには開発者ガイドに記載された追加要件があります。</p><h2 id="operational-details" tabindex="-1">運用の詳細 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;運用の詳細 {#operational-details}&quot;">​</a></h2><p>ウィンドウが開かない場合はネイティブの <code>tiktools.log</code>（コントローラーモードは <code>controller.log</code>）を確認します。Windows は <code>%LOCALAPPDATA%/TikTools/logs</code>、Linux は <code>${XDG_DATA_HOME:-~/.local/share}/TikTools/logs</code> ですが、<code>TIKTOOLS_HOME</code> または <code>TIKTOOLS_LOG_DIR</code> で変わります。ファイル作成前にログ初期化が失敗する場合もあります。端末のエラーを残し、共有前に<a href="./preferences/troubleshooting.html#operational-details">診断の保持とプライバシー</a>を確認してください。</p>',14)])])}const p=a(i,[["render",l]]);export{m as __pageData,p as default};
